function waveSize(){return 4+game.day}
function refreshHUD(){stats.innerHTML=`<div class="stat"><span>🪙</span>${game.gold}</div><div class="stat"><span>🪵</span>${game.wood}</div><div class="stat"><span>❤️</span>${game.health}</div>`;document.getElementById('seed-count').textContent=`Seeds ${game.seeds}`;const day=game.phase==='day';document.getElementById('phase-icon').textContent=day?'🌙':'⏳';document.getElementById('phase-label').innerHTML=day?'Start the night<small>Defend the farm!</small>':`Night ${game.day}<small>${game.spawned<waveSize()?'Moths incoming…':'Hold the line!'}</small>`;document.getElementById('hint').textContent=day?'Plant, water, and harvest crops. Each chore uses one of your actions.':'Tap an empty grove tile to build. Existing turrets can be upgraded!';document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===game.tool));document.querySelector('[data-tool="seed"]').classList.toggle('active',game.phase==='day'&&game.tool==='seed');document.querySelector('[data-tool="build"]').classList.toggle('active',game.phase==='night'&&game.tool==='build');}
function tick(dt){if(game.phase!=='night'||game.gameover)return;spawnClock+=dt;if(game.spawned<waveSize()&&spawnClock>2.05){spawnClock=0;game.enemies.push({x:922,y:128,leg:0,hp:game.day>2?3:2,max:game.day>2?3:2,speed:30+game.day*1.5,hit:false});game.spawned++;refreshHUD()}
const route=[[922,128],[824,128],[824,476],[877,476]];
for(const e of game.enemies){e.hit=false;let target=route[e.leg+1];if(!target)continue;let dx=target[0]-e.x,dy=target[1]-e.y,d=Math.hypot(dx,dy),step=e.speed*dt;if(d<=step){e.x=target[0];e.y=target[1];e.leg++;if(e.leg>=route.length-1){e.done=true;game.health=Math.max(0,game.health-1);say('A moon-moth reached your home!');}}else{e.x+=dx/d*step;e.y+=dy/d*step}}
game.enemies=game.enemies.filter(e=>!e.done);
for(const t of game.towers){t.cool=(t.cool||0)-dt;if(t.cool<=0){let cx=build.x+t.x*(build.size+build.gap)+31,cy=build.y+t.y*(build.size+build.gap)+31,target=game.enemies.filter(e=>Math.hypot(e.x-cx,e.y-cy)<205).sort((a,b)=>Math.hypot(a.x-cx,a.y-cy)-Math.hypot(b.x-cx,b.y-cy))[0];if(target){game.shots.push({x:cx,y:cy,target,damage:t.level>1?2:1,speed:360});t.cool=t.level>1?.52:.82}}}
for(const s of game.shots){if(!game.enemies.includes(s.target)){s.done=true;continue}let dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy),step=s.speed*dt;if(d<step+8){s.target.hp-=s.damage;s.target.hit=true;s.done=true;if(s.target.hp<=0){s.target.done=true;game.gold+=1;game.defeated++}}else{s.x+=dx/d*step;s.y+=dy/d*step}}
game.shots=game.shots.filter(s=>!s.done);game.enemies=game.enemies.filter(e=>!e.done);if(game.health<=0){game.gameover=true;refreshHUD();save();return}if(game.spawned>=waveSize()&&game.enemies.length===0){finishNight()}}
function finishNight(){game.phase='day';game.day++;game.actions=6;game.spawned=0;game.defeated=0;game.nightStarted=false;game.gold+=2;game.wood+=2;game.seeds+=1;for(const p of game.crops){if(p.stage===1&&p.water)p.stage=2;p.water=false}game.enemies=[];game.shots=[];game.tool='seed';say('Sunrise! +2 gold, +2 wood, +1 seed');refreshHUD();save()}
function spendAction(){if(game.actions<=0){say('All chores done — time for the night!');return false}game.actions--;return true}
function actAt(x,y){if(game.gameover)return;if(game.phase==='day'){if(x>=plot.x&&x<plot.x+4*(plot.size+plot.gap)-game.plotGap){/* grid resolved below */}
let c=Math.floor((x-plot.x)/(plot.size+plot.gap)),r=Math.floor((y-plot.y)/(plot.size+plot.gap));if(c<0||c>3||r<0||r>3)return;let inCell=x>=plot.x+c*(plot.size+plot.gap)&&x<=plot.x+c*(plot.size+plot.gap)+plot.size&&y>=plot.y+r*(plot.size+plot.gap)&&y<=plot.y+r*(plot.size+plot.gap)+plot.size;if(!inCell)return;let p=game.crops[r*4+c];if(game.tool==='seed'){if(p.stage){say('That bed is already growing!');return}if(!game.seeds){say('No seeds left — harvest crops to find more.');return}if(!spendAction())return;p.stage=1;p.water=false;game.seeds--;say('Seed planted! Give it a drink.')}else if(game.tool==='water'){if(!p.stage){say('Plant a seed here first.');return}if(p.water){say('Already watered!');return}if(!spendAction())return;p.water=true;say('A little drink for your crop 💧')}else if(game.tool==='harvest'){if(p.stage<2){say('Not ripe yet — water it and wait for sunrise.');return}if(!spendAction())return;p.stage=0;p.water=false;game.gold+=4;game.seeds++;say('Harvested! +4 gold and a seed 🌟')}refreshHUD();save();return}
if(game.phase==='night'&&game.tool==='build'){let c=Math.floor((x-build.x)/(build.size+build.gap)),r=Math.floor((y-build.y)/(build.size+build.gap));if(c<0||c>3||r<0||r>2)return;let bx=build.x+c*(build.size+build.gap),by=build.y+r*(build.size+build.gap);if(x<bx||x>bx+build.size||y<by||y>by+build.size)return;let t=game.towers.find(t=>t.x===c&&t.y===r);if(t){if(t.level>=3){say('This turret is fully upgraded!');return}if(game.gold<3||game.wood<2){say('Upgrade costs 3 gold and 2 wood.');return}game.gold-=3;game.wood-=2;t.level++;say('Turret upgraded!');}else{if(game.gold<2||game.wood<2){say('Build costs 2 gold and 2 wood.');return}game.gold-=2;game.wood-=2;game.towers.push({x:c,y:r,level:1,cool:0});say('Moonwatch turret built!')}refreshHUD();save()}}

